import{CategoryEnum}from"./types.js";const RECENTLY_USED_NAME="Recently used";function makeGroupTabs(categories,categoryBaseEmojis){const groupTabs=[];let groupId=0;for(const category of categories){groupTabs.push({name:RECENTLY_USED_NAME,icon:"emoji_picker_v2:emoji_recent",category:category,groupId:`${category}-history`,active:false,disabled:true,pagination:1});let pagination=1;categoryBaseEmojis[category]?.forEach((tab=>{pagination=tab.pagination||pagination;groupTabs.push({name:tab.name,icon:tab.icon,category:category,pagination:pagination,groupId:groupId.toString(),active:false,disabled:false});groupId++}))}return groupTabs}export const CATEGORY_METADATA=[{name:CategoryEnum.EMOJI,icon:"emoji_picker_v2:emoji_emojis_outlined",active:true},{name:CategoryEnum.SYMBOL,icon:"emoji_picker_v2:emoji_symbols",active:false},{name:CategoryEnum.EMOTICON,icon:"emoji_picker_v2:emoji_emoticons",active:false}];export const GIF_CATEGORY_METADATA=[...CATEGORY_METADATA,{name:CategoryEnum.GIF,icon:"emoji_picker_v2:emoji_gif",active:false}];export const CATEGORY_TABS={emoji:[{name:"Smileys & Emotions",icon:"emoji_picker_v2:emoji_emojis_filled",pagination:1},{name:"People",icon:"emoji_picker:emoji_people"},{name:"Animals & Nature",icon:"emoji_picker:emoji_nature"},{name:"Food & Drink",icon:"emoji_picker:emoji_food_beverage"},{name:"Travel & Places",icon:"emoji_picker:emoji_transportation"},{name:"Activities & Events",icon:"emoji_picker:emoji_events"},{name:"Objects",icon:"emoji_picker:emoji_objects"},{name:"Symbols",icon:"emoji_picker:emoji_symbols"},{name:"Flags",icon:"emoji_picker:flag"}],emoticon:[{name:"Classic",pagination:1},{name:"Smiling"},{name:"Love"},{name:"Hugging"},{name:"Flexing"},{name:"Animals",pagination:2},{name:"Surprising"},{name:"Dancing"},{name:"Shrugging"},{name:"Table Flipping",pagination:3},{name:"Disapproving"},{name:"Crying"},{name:"Worrying",pagination:4},{name:"Pointing"},{name:"Sparkling"}],symbol:[{name:"Arrows",pagination:1},{name:"Bullet/Stars"},{name:"Currency"},{name:"Letterlike",pagination:2},{name:"Math"},{name:"Miscellaneous"}]};export const SUBCATEGORY_TABS=makeGroupTabs(CATEGORY_METADATA.map((item=>item.name)),CATEGORY_TABS);const SUBCATEGORY_TABS_GIF_SUPPORT=makeGroupTabs(GIF_CATEGORY_METADATA.map((item=>item.name)),CATEGORY_TABS);export const gifCategoryTabs=categories=>makeGroupTabs(GIF_CATEGORY_METADATA.map((item=>item.name)),categories);export const TABS_CATEGORY_START_INDEX=new Map(SUBCATEGORY_TABS.map(((item,index)=>[item.category,index])).reverse());export const TABS_CATEGORY_START_INDEX_GIF_SUPPORT=new Map(SUBCATEGORY_TABS_GIF_SUPPORT.map(((item,index)=>[item.category,index])).reverse());export const EMOJI_GROUP_TABS=makeGroupTabs([CategoryEnum.EMOJI],CATEGORY_TABS);